-- Idempotent publisher-to-corpus data correction; preserves conflicting local reports.
INSERT INTO public.external_reference_map(hadith_corpus_id,site,external_reference,url,verified_by,verified_on) SELECT 18204,'sunnah.com','3052','https://sunnah.com/abudawud:3052','Publisher Arabic chain (Sulayman ibn Dawud, Ibn Wahb, Abu Sakhr, Safwan) and English contracting-person protections matched. Local 81862 contains a different report and is preserved as an unverified catalogue collision.',DATE '2026-10-25' WHERE EXISTS (SELECT 1 FROM public.hadith_corpus WHERE id=18204 AND collection='Sunan Abu Dawud' AND hadith_number='3052') AND NOT EXISTS (SELECT 1 FROM public.external_reference_map WHERE site='sunnah.com' AND external_reference='3052');
